<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesUidVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesAudienceVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesVersionVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesListRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesItem;
use PHPUnit\Framework\TestCase;

class TrustedClientAllowedAudiencesListRefUnitTest extends TestCase
{
    public function test_iterator(): void
    {
        $one = new TrustedClientAllowedAudiencesItem(
            uid: TrustedClientAllowedAudiencesUidVO::from('one'),
            audience: TrustedClientAllowedAudiencesAudienceVO::from('one'),
            version: TrustedClientAllowedAudiencesVersionVO::from(1)
        );
        $two = new TrustedClientAllowedAudiencesItem(
            uid: TrustedClientAllowedAudiencesUidVO::from('one'),
            audience: TrustedClientAllowedAudiencesAudienceVO::from('one'),
            version: TrustedClientAllowedAudiencesVersionVO::from(1)
        );
        $list = TrustedClientAllowedAudiencesListRef::fromArray([$one, $two]);
        foreach ($list as $_K => $item) {
            $this->assertEquals('one', $item->uid());
        }
    }
    public function test_invalid_builder(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        $list = TrustedClientAllowedAudiencesListRef::fromArray(['none']);
    }
}
